import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        // Simulate that caller has some unclaimed shares (in a real scenario this would be set via deposit, but we assume positive)
        // To keep the test simple and general, we only check that claim does not revert when caller has zero unclaimed shares
        // The general rule: claim(caller, amount) should revert if amount > 0 (due to InsufficientShares)
        bool attemptsRevert;
        try c.claim(caller, amount) {
            attemptsRevert = false;
        } catch {
            attemptsRevert = true;
        }
        // The reference satisfies: claim reverts if amount > 0 and caller has no shares
        // The mutant (owner() returns address(0)) might break due to different behavior in transfer
