pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address expectedOwner;

    function setUp() public { 
        c = new C();
        expectedOwner = c.owner();
    }

    function testFuzz_property(address caller, uint256 amount) public {
        // Bound amount to a reasonable range to avoid reverts due to insufficient balance
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // Attempt to call claim (may revert due to various reasons, but our rule is about owner() after call)
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.claim.selector, caller, amount));

        // The general rule: immediately after any call (whether it succeeds or reverts),
        // the owner() getter must return the same value as at deployment time.
        assertTrue(c.owner() == expectedOwner, "owner() changed after call");
    }
}

