        // Simpler approach: The bug makes depositToken always revert, so dnGmxJuniorVaultGlpBalance (public uint256) is never increased.
        // After a claim that reverts (e.g., due to insufficient shares), the state should remain unchanged.
        // We can check that dnGmxJuniorVaultGlpBalance remains 0 after any attempt.

        uint256 balanceBefore = c.dnGmxJuniorVaultGlpBalance();
        // Call claim; it may revert if the claimer has no shares, which is fine
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.claim.selector, claimer, amount));
        // After the call, the balance should not increase
        uint256 balanceAfter = c.dnGmxJuniorVaultGlpBalance();
        assertTrue(balanceAfter <= balanceBefore, "sGlp balance increased during claim");
    }
}

