pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address anyUser, address receiver, uint256 amount) public {
        // Ensure we have a non-zero amount and a non-zero receiver
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount <= 1e30); // avoid overflow

        // Record the vault's balance of the receiver before claim
        uint256 balanceBefore = c.dnGmxJuniorVault().balanceOf(receiver);

        // Attempt to claim with the given parameters
        // We use try/catch because the call may revert
        uint256 shareAmount = amount % (1e30); // bound to a reasonable range
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.claim.selector, receiver, shareAmount));

        // Rule: if the call succeeded, the receiver's balance in the vault should not have decreased
        if (success) {
            uint256 balanceAfter = c.dnGmxJuniorVault().balanceOf(receiver);
            assertTrue(balanceAfter >= balanceBefore, "Vault balance decreased after claim");
        } else {
            // If reverted, no state change should have occurred; balance stays same
            uint256 balanceAfter = c.dnGmxJuniorVault().balanceOf(receiver);
            assertTrue(balanceAfter == balanceBefore, "Vault balance changed on revert");
        }
    }
}
